import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { getAllCities, getAllCountries, getAllStates } from '../../../app/store/slices/cities';
import { getEventsList } from '../../../app/store/slices/event/event';
import { getAllSacCodes } from '../../../app/store/slices/gst-rates/gst';
import { getAllBankDetailByUserId } from '../../../app/store/slices/bank/bank';

export default function useUserDashboard() {
    const dispatch = useDispatch();

    const { user, isLoggedIn } = useSelector((state) => state.auth);
    const { cities, states, countries } = useSelector((state) => state.cities);
    const { eventData } = useSelector((state) => state.event);
    const { sacCodes } = useSelector((state) => state.gst);
    const { bankDetails } = useSelector((state) => state.bank);

    useEffect(() => {
        if (user?.id && isLoggedIn) {
            if (cities?.length === 0 || !cities) {
                dispatch(getAllCities());
            }

            if (states?.length === 0 || !states) {
                dispatch(getAllStates());
            }

            if (countries?.length === 0 || !countries) {
                dispatch(getAllCountries());
            }
        }
    }, [user?.id]);

    useEffect(() => {
        if (user?.id && isLoggedIn) {
            if (bankDetails?.length === 0 || !bankDetails) {
                dispatch(getAllBankDetailByUserId({ user_id: user?.id }));
            }
        }
    }, [user?.id, isLoggedIn, bankDetails]);

    useEffect(() => {
        if (user?.id && isLoggedIn) {
            if (sacCodes?.length === 0 || !sacCodes) {
                dispatch(getAllSacCodes());
            }
        }
    }, [user?.id]);

    useEffect(() => {
        if ((eventData?.length === 0 || !eventData) && user?.id) {
            dispatch(getEventsList());
        }
    }, [eventData, user?.id]);
}
