import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import { Button } from '@mui/material';
import { useLocation } from 'react-router-dom';
import ListItem from '../../../layout/MenuList/ListItem/ListItem';
import ListCollapse from '../../../layout/MenuList/ListCollapse/ListCollapse';
import { settingsMenus, mainMenus } from '../../../layout/user-menus-list/userMenuList';
import '../../../styles/components/Sidebar.css';

export default function Sidebar() {
    const { user } = useSelector((state) => state.auth);
    const location = useLocation();
    const currentPath = location.pathname;

    // Use useMemo to memoize the currently selected menu item based on the current path
    const selectedItems = useMemo(() => {
        // Find if the current path matches any of in the main menus
        const mainSelected = mainMenus.find(
            (item) =>
                item.url === currentPath ||
                (item.children && item.children.some((child) => child.url === currentPath))
        );

        // Find if the current path matches any of in the settings menus
        const settingSelected = settingsMenus.find((item) => item.url === currentPath);

        // Return the IDs of the selected main and setting menus, and the current path for child selection
        return {
            mainSelectedId: mainSelected?.id || '',
            settingSelectedId: settingSelected?.id || '',
            // Track if it's a child item that's selected
            childSelectedUrl: currentPath
        };
    }, [currentPath]);

    const isItemSelected = (item) => {
        if (item.type === 'item') {
            return item.url === selectedItems.childSelectedUrl;
        } else if (item.type === 'collapse') {
            return item.id === selectedItems.mainSelectedId;
        }
        return false;
    };

    return (
        <React.Fragment>
            <aside id="event-dashboard-sidebar">
                <div className="go-back-container">
                    <Button
                        fullWidth
                        size="large"
                        variant="text"
                        sx={{ ...backBtnStyle, cursor: 'default' }}
                        disableRipple
                    >
                        Hi, {user?.name || 'User'}
                    </Button>
                </div>
                <div className="event-dashboard-tabs-container">
                    <div className="event-dashboard-main-tabs">
                        {mainMenus.map((item) => {
                            if (item.type === 'item') {
                                return (
                                    <ListItem
                                        key={item.id}
                                        tabName={item.title}
                                        icon={item.icon}
                                        url={item.url}
                                        isSelected={isItemSelected(item)}
                                    />
                                );
                            } else if (item.type === 'collapse') {
                                return (
                                    <ListCollapse
                                        key={item.id}
                                        tabName={item.title}
                                        icon={item.icon}
                                        children={item.children}
                                        selectedChildUrl={selectedItems.childSelectedUrl}
                                    />
                                );
                            }
                            return null;
                        })}
                    </div>
                    <div className="event-settings-log-out-tabs">
                        <div className="event-setting-tabs">
                            {settingsMenus.map((item) => (
                                <ListItem
                                    key={item.id}
                                    tabName={item.title}
                                    icon={item.icon}
                                    url={item.url}
                                    isSelected={item.id === selectedItems.settingSelectedId}
                                />
                            ))}
                        </div>
                    </div>
                </div>
            </aside>
        </React.Fragment>
    );
}

const backBtnStyle = {
    color: 'var(--quaternary-color)',
    textTransform: 'capitalize',
    fontFamily: 'Nunito, sans-serif',
    fontSize: '1.25rem',
    justifyContent: 'flex-start',
    borderRadius: '0.625rem'
};
