import { useMemo } from 'react';

/**
 * @function useActiveMenuName
 * @description Custom hook to derive a human-readable active menu name from the current pathname (URL).
 * @param {string} pathname - The current URL pathname.
 * @returns {string} - The formatted active menu name.
 * @example
 * const activeMenuName = useActiveMenuName('/dashboard/user-settings');
 * activeMenuName would be 'User Settings'
 */
export default function useActiveMenuName(pathname) {
    return useMemo(() => {
        const parts = pathname.split('/').filter(Boolean); // remove empty segments

        const last = parts[parts.length - 1] || '';

        if (!last) return '';

        return decodeURIComponent(last)
            .split('-')
            .filter(Boolean)
            .map(w => w.charAt(0).toUpperCase() + w.slice(1))
            .join(' ');

    }, [pathname]);
}